def main():
    for n, (verdict, nxt) in V.items():
        p = os.path.join(PLANS, f'gen_{n:03d}.json')
        plan = json.load(open(p, encoding='utf8'))
        plan['verdict'] = verdict
        plan['next'] = plan.get('next') or nxt
        json.dump(plan, open(p, 'w', encoding='utf8'), ensure_ascii=False, indent=2)
    print('verdicts:', sorted(V))


if __name__ == '__main__':
    main()
